import{_ as a,o as d,c as e,a2 as n}from"./chunks/framework.F7eQ-ohH.js";const s="/bzygq/assets/fde3189480424c3d94138091c77a1bcf.BIuJ8woZ.png",r="/bzygq/assets/55a40418708145bbb3d37aee79d69e99.D13gft2N.png",m=JSON.parse('{"title":"Embedding与RAG检索基础","description":"","frontmatter":{},"headers":[],"relativePath":"AI应用开发/二、LLM教程/Embedding与RAG检索基础.md","filePath":"AI应用开发/二、LLM教程/Embedding与RAG检索基础.md","lastUpdated":1788883925000}'),i={name:"AI应用开发/二、LLM教程/Embedding与RAG检索基础.md"};function p(l,t,o,h,b,c){return d(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="embedding与rag检索基础" tabindex="-1">Embedding与RAG检索基础 <a class="header-anchor" href="#embedding与rag检索基础" aria-label="Permalink to &quot;Embedding与RAG检索基础&quot;">​</a></h1><p><img src="'+s+'" alt=""></p><p>Embedding 是把文本映射成向量的过程。向量可以理解为一组数字坐标，模型通过这些数字来表示文本的语义。在大模型应用开发中，Embedding 最常见的用途不是聊天，而是检索。比如企业制度知识库里有很多文件，系统会先把文件切成片段，再把每个片段转成向量，存入向量数据库。当用户提问时，系统也把问题转成向量，然后查找语义上最接近的文档片段。</p><h2 id="一、embedding-和生成模型的区别" tabindex="-1">一、Embedding 和生成模型的区别 <a class="header-anchor" href="#一、embedding-和生成模型的区别" aria-label="Permalink to &quot;一、Embedding 和生成模型的区别&quot;">​</a></h2><p>这里要区分两个概念：</p><table tabindex="0"><thead><tr><th>概念</th><th>主要作用</th><th>常见场景</th></tr></thead><tbody><tr><td>生成模型</td><td>根据上下文生成回答</td><td>问答、写作、总结、代码生成</td></tr><tr><td>Embedding 模型</td><td>把文本转成向量</td><td>语义搜索、相似度匹配、知识库检索</td></tr></tbody></table><p>很多同学会把它们混在一起。面试时可以强调：生成模型负责“组织答案”，Embedding 模型负责“找到相关材料”。RAG 的效果不好，不一定是生成模型差，也可能是文档切分、向量模型、召回策略或上下文拼接出了问题。</p><h2 id="二、rag-的基本链路" tabindex="-1">二、RAG 的基本链路 <a class="header-anchor" href="#二、rag-的基本链路" aria-label="Permalink to &quot;二、RAG 的基本链路&quot;">​</a></h2><p>RAG 可以理解为“先查资料，再让模型回答”。它不是让模型凭记忆回答，而是先从外部知识库里找相关材料，再把材料和问题一起交给模型，常见链路是：</p><p><img src="'+r+`" alt=""></p><p>RAG 的完整流程可以分成两个阶段。第一阶段是离线知识库构建：先上传企业文档，再进行文档解析、文本切分，将切分后的内容生成 Embedding 向量，并写入向量数据库。第二阶段是在线问答生成：用户提出问题后，系统先把问题向量化，再到向量数据库中检索相似内容，召回相关文档片段，最后把用户问题和召回依据一起拼接成 Prompt，交给大模型生成答案。RAG 的核心价值，就是让大模型不要只凭自身参数“猜答案”，而是基于企业知识库中召回的材料进行回答。</p><h2 id="三、为什么-rag-能减少幻觉" tabindex="-1">三、为什么 RAG 能减少幻觉 <a class="header-anchor" href="#三、为什么-rag-能减少幻觉" aria-label="Permalink to &quot;三、为什么 RAG 能减少幻觉&quot;">​</a></h2><p>大模型容易幻觉，一个重要原因是它没有实时、权威、专属的业务知识。RAG 的价值就是把企业内部知识源接进来，让模型基于召回材料回答。</p><p>但要注意，RAG 只能降低幻觉风险，不能自动保证答案正确。因为 RAG 链路里每一步都可能出问题：</p><table tabindex="0"><thead><tr><th>环节</th><th>可能问题</th></tr></thead><tbody><tr><td>文档解析</td><td>PDF 表格、图片、页眉页脚识别错误</td></tr><tr><td>文本切分</td><td>一段话被切断，语义不完整</td></tr><tr><td>向量化</td><td>Embedding 模型不适合当前行业语料</td></tr><tr><td>召回</td><td>找到相似但不相关的片段</td></tr><tr><td>重排</td><td>排名靠前的片段不是最关键证据</td></tr><tr><td>Prompt 拼接</td><td>材料太多、冲突或顺序混乱</td></tr><tr><td>生成回答</td><td>模型没有严格依据材料回答</td></tr></tbody></table><p>所以做 RAG 项目，不能只说“我用了向量数据库”，还要说明你如何处理文档、如何切分、如何召回、如何约束回答。</p><h2 id="四、项目表达模板" tabindex="-1">四、项目表达模板 <a class="header-anchor" href="#四、项目表达模板" aria-label="Permalink to &quot;四、项目表达模板&quot;">​</a></h2><p>项目里可以这样说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我没有直接把全部文档交给大模型，而是先对文档进行解析和切分，</span></span>
<span class="line"><span>再使用 Embedding 模型生成向量并写入向量数据库。</span></span>
<span class="line"><span>用户提问时，系统先做语义检索，召回相关片段，再把片段和问题一起交给大模型生成回答。</span></span>
<span class="line"><span>这样可以减少模型胡编，同时降低上下文消耗。</span></span></code></pre></div><p>如果面试官追问“召回不准怎么办”，可以补充：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我会从几个方向优化：一是调整切分粒度，避免片段过长或过短；</span></span>
<span class="line"><span>二是增加关键词检索和向量检索的混合召回；</span></span>
<span class="line"><span>三是增加 rerank，把更相关的片段排到前面；</span></span>
<span class="line"><span>四是在 Prompt 中要求模型只基于材料回答，并返回引用来源。</span></span></code></pre></div><h2 id="五、面试常问问题" tabindex="-1">五、面试常问问题 <a class="header-anchor" href="#五、面试常问问题" aria-label="Permalink to &quot;五、面试常问问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>回答重点</th></tr></thead><tbody><tr><td>Embedding 是什么？</td><td>把文本转成语义向量，便于相似度检索</td></tr><tr><td>RAG 为什么重要？</td><td>让模型结合外部知识回答，降低幻觉</td></tr><tr><td>向量数据库存什么？</td><td>文档片段向量、文本内容、来源、元数据</td></tr><tr><td>召回不准怎么办？</td><td>切分优化、混合检索、rerank、查询改写</td></tr><tr><td>RAG 和微调有什么区别？</td><td>RAG 适合接入外部知识，微调更适合改变模型行为或风格</td></tr></tbody></table>`,23)])])}const _=a(i,[["render",p]]);export{m as __pageData,_ as default};
